  "fr": {
   "title": "Le terrain penche",
   "subtitle": "10 contre 10 : chaque minute dans le dernier tiers adverse rapporte un point",
   "objective": "Installer la possession dans le dernier tiers adverse et l'y garder, par la circulation et la contre-pression. On rend visible le field tilt : la part de la possession jouée dans le dernier tiers.",
   "organisation": [
    "Terrain entier, ou 90 x 64 m pour les U15 ; les deux derniers tiers sont marqués par des coupelles.",
    "Deux équipes de 10 joueurs de champ et un gardien.",
    "Un adjoint par équipe, chronomètre en main, au bord du dernier tiers adverse.",
    "Le chrono tourne quand l'équipe a le ballon dans ce tiers ; il s'arrête quand le ballon en sort ou est perdu."
   ],
   "rules": [
    "Chaque minute cumulée de possession dans le dernier tiers adverse rapporte 1 point.",
    "Un but vaut 2 points.",
    "Ballon repris dans les 5 secondes sans sortir du tiers : le chrono continue.",
    "Un long ballon ne lance pas le chrono : il faut une passe contrôlée ou une conduite dans le tiers.",
    "Règles normales, hors-jeu compris ; l'adjoint annonce chaque point à voix haute."
   ],
   "coaching": [
    "Entrez dans le tiers à plusieurs : un joueur seul ne fait pas pencher le terrain.",
    "Circule autour du bloc, de la largeur vers l'intérieur, sans forcer : le chrono tourne pour toi.",
    "Défense de repos haute, au bord du tiers : c'est elle qui ramasse les ballons repoussés.",
    "À la perte, reprends tout de suite : cinq secondes pour garder le terrain penché.",
    "Posséder ne suffit pas : quand la passe vers la surface s'ouvre, joue-la."
   ],
   "progressions": [
    "Le chrono ne tourne que si au moins 5 joueurs de l'équipe sont dans le tiers.",
    "Deux touches maximum dans le dernier tiers.",
    "Le chrono s'arrête aussi après 30 secondes sans tir."
   ],
   "regressions": [
    "Le point tombe toutes les 30 secondes cumulées.",
    "Un joker joue avec l'équipe en possession.",
    "Le dernier tiers est agrandi à 40 m."
   ],
   "measure": "Temps de possession de chaque équipe dans le dernier tiers adverse, divisé par le temps total des deux équipes dans ces tiers : c'est le field tilt. À relier aux récupérations en moins de 5 secondes dans ce tiers.",
   "story": "À Waldorf, Marcus Bell montre sur sa tablette que le terrain a penché du côté de l'équipe qui reprenait le ballon le plus vite."
  },
  "en": {
   "title": "Tilting the Pitch",
   "subtitle": "10 v 10: every minute in the opposition final third earns a point",
   "objective": "Set up possession in the opposition final third and keep it there, through ball circulation and counter-pressing. It makes field tilt visible: the share of possession played in the final third.",
   "organisation": [
    "Full pitch, or 90 x 64 m for U15s; both final thirds are marked with disc cones.",
    "Two teams of 10 outfield players and a goalkeeper.",
    "One assistant per team, stopwatch in hand, beside the opposition final third.",
    "The clock runs while the team has the ball in that third; it stops when the ball leaves it or is lost."
   ],
   "rules": [
    "Every cumulative minute of possession in the opposition final third earns 1 point.",
    "A goal is worth 2 points.",
    "Ball won back within 5 seconds without leaving the third: the clock keeps running.",
    "A long ball does not start the clock: it takes a controlled pass or a dribble into the third.",
    "Normal rules, offside included; the assistant calls out every point."
   ],
   "coaching": [
    "Go into the third in numbers: one player alone does not tilt the pitch.",
    "Move the ball around the block, from wide to inside, without forcing it: the clock is running for you.",
    "High rest defence, on the edge of the third: they pick up the cleared balls.",
    "When you lose it, win it back at once: five seconds to keep the pitch tilted.",
    "Having the ball is not enough: when the pass into the box opens, play it."
   ],
   "progressions": [
    "The clock only runs if at least 5 players of the team are in the third.",
    "Two touches maximum in the final third.",
    "The clock also stops after 30 seconds without a shot."
   ],
   "regressions": [
    "A point every 30 cumulative seconds.",
    "A joker plays with the team in possession.",
    "The final third is extended to 40 m."
   ],
   "measure": "Each team's possession time in the opposition final third, divided by both teams' total time in those thirds: that is field tilt. Link it to the number of regains within 5 seconds in that third.",
   "story": "In Waldorf, Marcus Bell shows on his tablet that the pitch tilted towards the team that won the ball back fastest."
  },
