  "fr": {
   "title": "Le déclencheur",
   "subtitle": "Bloc médian à 6 contre 6 + gardien : presser ensemble au signal, finir en 10 secondes",
   "objective": "Défendre pour récupérer : attendre en bloc médian, compact, puis presser tous ensemble sur un déclencheur. Après la récupération, finir vite, avant que l'adversaire ne se réorganise.",
   "organisation": [
    "Une moitié de terrain (52 x 68 m), un grand but avec gardien, deux mini-buts sur la ligne médiane.",
    "Équipe B, en possession : gardien et 6 joueurs (4 défenseurs, 2 milieux) qui sortent vers les mini-buts.",
    "Équipe A, qui défend : 6 joueurs en bloc médian, 2 devant et 4 derrière.",
    "Une ligne de coupelles à 30 m du but marque la limite du bloc.",
    "Chaque action part du gardien de B ; 6 à 8 actions par série, puis on change les rôles."
   ],
   "rules": [
    "Avant le déclencheur, aucun joueur de A ne franchit la ligne des 30 m.",
    "Déclencheurs : passe en arrière, mauvais contrôle, ballon vers un latéral près de la touche, ou appel de l'entraîneur.",
    "Au déclencheur, tout le bloc presse ensemble.",
    "A récupère et marque en moins de 10 secondes : 3 points ; tir cadré : 1 point.",
    "B marque 1 point en passant dans un mini-but ou en conduisant le ballon au-delà de la ligne médiane."
   ],
   "coaching": [
    "Avant le signal : compacts, 10 à 12 m entre les lignes, l'axe fermé.",
    "Le premier attaquant oriente : il coupe la passe vers le central opposé et pousse vers la touche.",
    "Au signal, tout le monde avance en même temps : un joueur seul qui presse, c'est un trou.",
    "Le plus proche presse le porteur, les autres prennent les passes courtes.",
    "Ballon récupéré : regarde devant, le but est à 30 m.",
    "Pas de déclencheur ? Restez en place, avec patience."
   ],
   "progressions": [
    "L'entraîneur n'appelle plus : les joueurs reconnaissent seuls les déclencheurs.",
    "B joue avec un pivot en plus : 7 contre 6.",
    "Finir en moins de 8 secondes."
   ],
   "regressions": [
    "Un seul déclencheur au début : la passe en arrière.",
    "B joue à deux touches maximum.",
    "Finir en moins de 15 secondes."
   ],
   "measure": "Récupérations dans les 30 m adverses et part de ces récupérations suivies d'un tir en moins de 10 secondes. L'analyste peut aussi suivre la hauteur moyenne des récupérations.",
   "story": "À Londres, au début, BriBri presse seul et se fait éliminer d'une passe. Coach Okafor lui montre que le pressing est une décision d'équipe."
  },
  "en": {
   "title": "The Trigger",
   "subtitle": "Mid-block 6 v 6 + goalkeeper: press together on the cue, finish within 10 seconds",
   "objective": "Defend to win the ball: wait in a compact mid-block, then press all together on a trigger. After the regain, finish quickly, before the opponent can reorganise.",
   "organisation": [
    "Half a pitch (52 x 68 m), a full-size goal with a goalkeeper, two mini goals on the halfway line.",
    "Team B, in possession: goalkeeper and 6 players (4 defenders, 2 midfielders) building out towards the mini goals.",
    "Team A, defending: 6 players in a mid-block, 2 in front and 4 behind.",
    "A line of cones 30 m from goal marks the edge of the block.",
    "Every move starts from B's goalkeeper; 6 to 8 moves per set, then swap roles."
   ],
   "rules": [
    "Before the trigger, no A player may cross the 30 m line.",
    "Triggers: a back pass, a heavy touch, a ball to a full-back near the touchline, or the coach's call.",
    "On the trigger, the whole block presses together.",
    "A wins the ball and scores within 10 seconds: 3 points; shot on target: 1 point.",
    "B scores 1 point by passing into a mini goal or dribbling over the halfway line."
   ],
   "coaching": [
    "Before the cue: compact, 10 to 12 m between the lines, middle closed.",
    "The first forward shows them one way: he cuts the pass to the far centre-back and pushes play to the touchline.",
    "On the cue, everyone steps up together: one player pressing alone leaves a hole.",
    "The nearest player presses the ball, the others take the short passes.",
    "Ball won: look forward, the goal is 30 m away.",
    "No trigger? Stay in shape, be patient."
   ],
   "progressions": [
    "The coach stops calling: players must recognise the triggers on their own.",
    "B adds a pivot: 7 v 6.",
    "Finish within 8 seconds."
   ],
   "regressions": [
    "Only one trigger at first: the back pass.",
    "B plays two touches maximum.",
    "Finish within 15 seconds."
   ],
   "measure": "Regains within 30 m of the opposition goal and the share of those regains followed by a shot within 10 seconds. The analyst can also track the average height of regains.",
   "story": "In London, BriBri presses alone at first and is beaten by one pass. Coach Okafor shows him that pressing is a team decision."
  },
